// Auto-generated Japan Prefectures Map Vector Data
export interface JapanPrefecturePathItem {
  id: string;
  name: { cs: string; en: string; ja: string; ru: string };
  hasPokelid: boolean;
  pokelidCount: number;
  ambassadorPokemon?: string;
  path: string;
}

export interface PrefectureLocalMapInfo {
  prefId: string;
  viewBox: string;
  bounds: { minLng: number; maxLng: number; minLat: number; maxLat: number };
  path: string;
}

export interface PokelidMapPin {
  id: string;
  x: number;
  y: number;
  label: { cs: string; en: string; ja: string; ru: string };
  pokemon: string;
  count: number;
  region: string;
}

export function projectCoordinatesToLocalMap(lat: number, lng: number, localMap: PrefectureLocalMapInfo): { x: number; y: number } {
  const pad = 40;
  const w = 500 - 2 * pad;
  const h = 400 - 2 * pad;
  const { minLng, maxLng, minLat, maxLat } = localMap.bounds;
  const scaleLng = w / (maxLng - minLng);
  const scaleLat = h / (maxLat - minLat);
  const scale = Math.min(scaleLng, scaleLat);
  const offX = pad + (w - (maxLng - minLng) * scale) / 2;
  const offY = pad + (h - (maxLat - minLat) * scale) / 2;
  const x = offX + (lng - minLng) * scale;
  const y = 400 - (offY + (lat - minLat) * scale);
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
}

